# ---------------------------------------------------------------- 書きやすくする道具
def _pair(v):
    if v is None:
        return None
    if isinstance(v, (list, tuple)):
        v = list(v)
        return v + [""] * (2 - len(v)) if len(v) < 2 else v
    return [v, ""]


def F(no, ja, sel, kind, trig="view", **kw):
    """項目1行。vi は空（最後にまとめて翻訳）。文字の項目は日本語だけ書けば [日本語, ""] にする"""
    d = {"no": no, "ja": ja, "vi": "", "sel": sel, "kind": kind, "trig": trig}
    for k, v in kw.items():
        if v is None or v == "" or v == [] or (isinstance(v, (list, tuple)) and v and not v[0] and k != "err"):
            continue
        if k in ("detail", "init", "cond", "valid", "open", "demo_ok", "chk", "ex"):
            d[k] = _pair(v)
        elif k == "len" and isinstance(v, (list, tuple)):
            d[k] = _pair(v)
        else:
            d[k] = v
    return d


def pick(items, *nos):
    by = {it["no"]: it for it in items}
    return [by[n] for n in nos]


def V(id, code, ja, url, items, setup="", note="", full=True, wait=900):
    return {"id": id, "code": code, "state": [ja, ""], "url": url, "setup": (JS + setup) if setup else "", "full": full, "wait": wait,
            "note": [note, ""], "items": items}


